import AppTrackingTransparency
import AdjustSdk

func showATTFlow(from vc: UIViewController) {
    // 1. Check the value-perception moment (e.g. onboarding done)
    guard OnboardingState.shared.isCompleted else { return }

    // 2. Show the pre-prompt
    let pre = PrePromptViewController(
        title: "Consent for personalized recommendations",
        body: "If you choose 'Allow' on the next screen, we can recommend content that better matches your interests.",
        primaryAction: "Continue",
        secondaryAction: "Skip for now"
    )
    pre.onPrimary = { requestSystemATT() }
    pre.onSecondary = { /* queue retry after 7 days */ }
    vc.present(pre, animated: true)
}

func requestSystemATT() {
    ATTrackingManager.requestTrackingAuthorization { status in
        // The Adjust SDK receives the result automatically
        Analytics.track("att_response", [
            "status": status.rawValue,
            "is_authorized": status == .authorized
        ])
    }
}

{
  "NSUserTrackingUsageDescription":
